// LSD 2.0 canonical media model and container-neutral sample index.
public sealed class LsdMediaModel {
 public string SourcePath="",ContainerType="Unknown",ContainerDetail="",AdapterName="MatroskaToLsdAdapter/2.0";
 public long FileLength,TimecodeScale=1000000; public double DurationSeconds;
 public readonly System.Collections.Generic.List<LsdTrackModel> Tracks=new System.Collections.Generic.List<LsdTrackModel>();
 public bool IsValid{get{return ContainerType!="Unknown"&&Tracks.Count>0;}}
 public int CountType(string kind){int n=0;foreach(var t in Tracks)if(t.TrackType==kind)n++;return n;}
}
public sealed class LsdTrackModel {
 public long TrackId; public string TrackType="other",CodecId="",CodecFamily="Unknown",Language="und",PayloadFormat="Unknown";
 public byte[] CodecPrivate; public int NalLengthSize,PcmBitDepth,PcmBlockAlign; public bool PcmFloat,PcmBigEndian; public long Width,Height,Channels; public double SamplingRate;
 public readonly System.Collections.Generic.List<LsdSampleModel> Samples=new System.Collections.Generic.List<LsdSampleModel>();
}
public sealed class LsdSampleModel {
 public long TrackId,FileOffset=-1,Length,DecodeTimestamp,PresentationTimestamp,Duration;
 public bool IsKeyFrame,IsDiscardable,IsInvisible; public int DescriptionIndex=1; public string PayloadFormat="Unknown";
}
public sealed class LsdCodecPacket {
 public string CodecFamily="Unknown",PayloadFormat="Unknown"; public long TrackId,FileOffset=-1,PayloadLength,DecodeTimestamp,PresentationTimestamp,Duration;
 public bool IsContainerKeyFrame; public int NalLengthSize; public byte[] CodecPrivate;
}
public static class LsdMatroskaAdapter {
 static string Family(string id){if(id=="V_MPEG4/ISO/AVC")return "AVC";if(id=="V_MPEGH/ISO/HEVC")return "HEVC";if(id=="V_MPEGI/ISO/VVC")return "VVC";if(id=="V_AV1")return "AV1";if(id=="V_AV2")return "AV2";if(id=="V_MPEG4/ISO/ASP")return "MPEG4ASP";if(id=="V_VP8")return "VP8";if(id=="V_VP9")return "VP9";if(id=="A_AAC")return "AAC";if(id=="A_EAC3"||id=="A_E-AC-3")return "EAC3";if(id!=null&&id.StartsWith("A_AC3"))return "AC3";if(id!=null&&id.StartsWith("A_MPEG/L3"))return "MP3";if(id!=null&&id.StartsWith("A_PCM"))return "PCM";return "Unknown";}
 static string Payload(string f){if(f=="AVC"||f=="HEVC"||f=="VVC")return "LengthPrefixedNal";if(f=="AV1")return "Av1Obu";if(f=="MPEG4ASP")return "Mpeg4Visual";if(f=="VP8")return "Vp8Frame";if(f=="VP9")return "Vp9Frame";return "RawCodecFrame";}
 public static LsdMediaModel Adapt(string path,NativeMediaInfo n){if(n==null)throw new ArgumentNullException("n");var m=new LsdMediaModel();m.SourcePath=path??"";m.ContainerType=n.Container??"Unknown";m.ContainerDetail=n.Detail??"";m.FileLength=n.Length;m.DurationSeconds=n.DurationSeconds;m.TimecodeScale=n.TimecodeScale;foreach(var x in n.Tracks){var t=new LsdTrackModel();t.TrackId=x.Number;t.TrackType=x.Kind;t.CodecId=x.CodecId??"";t.CodecFamily=Family(x.CodecId);t.Language=x.Language??"und";t.CodecPrivate=x.CodecPrivate;t.PayloadFormat=x.VfwFourcc&&t.CodecFamily=="AVC"?"AnnexBNal":Payload(t.CodecFamily);t.NalLengthSize=x.NalLengthSize;t.Width=x.Width;t.Height=x.Height;t.Channels=x.AudioChannels>0?x.AudioChannels:x.Channels;t.SamplingRate=x.OutputSampleRate>0?x.OutputSampleRate:x.SamplingRate;t.PcmBitDepth=x.PcmBitDepth;t.PcmBlockAlign=x.PcmBlockAlign;t.PcmFloat=x.PcmFloat;t.PcmBigEndian=x.PcmBigEndian;m.Tracks.Add(t);}return m;}
 public static LsdCodecPacket CreatePacket(LsdTrackModel t,LsdSampleModel s){return new LsdCodecPacket{CodecFamily=t.CodecFamily,PayloadFormat=s.PayloadFormat,TrackId=t.TrackId,FileOffset=s.FileOffset,PayloadLength=s.Length,DecodeTimestamp=s.DecodeTimestamp,PresentationTimestamp=s.PresentationTimestamp,Duration=s.Duration,IsContainerKeyFrame=s.IsKeyFrame,NalLengthSize=t.NalLengthSize,CodecPrivate=t.CodecPrivate};}
}

public sealed class CanonicalAudioAnalysisResult {
 public string CodecFamily="Unknown",PayloadFormat="Unknown",FirstError="",DolbyCodec="",DolbyLayout="",PcmFormat=""; public long Samples,PayloadBytes,Minimum=Int64.MaxValue,Maximum,Rejected,MpegAudioFrames,MpegAudioBytes,MpegAudioPcmSamples,DolbyFrames,DolbyBytes,DolbyRejected,DolbyPcmSamples; public double DurationSeconds,Bitrate,Average,PcmDecodedDuration; public int PcmBitDepth,PcmBlockAlign,PcmChannels,PcmSampleRate; public bool PcmFloat,PcmBigEndian; public int MpegVersion,Layer,SampleRate,Channels,MinimumFrameBitrate=Int32.MaxValue,MaximumFrameBitrate,DolbySampleRate,DolbyChannels;
 public bool Complete{get{return Samples>0&&Rejected==0;}}
}
public static class CanonicalAudioAnalyzer {
 static int Bitrate(int version,int layer,int index){int[,] m1={{0,32,40,48,56,64,80,96,112,128,160,192,224,256,320,0},{0,32,48,56,64,80,96,112,128,160,192,224,256,320,384,0},{0,32,40,48,56,64,80,96,112,128,160,192,224,256,320,0}};int[,] m2={{0,8,16,24,32,40,48,56,64,80,96,112,128,144,160,0},{0,8,16,24,32,40,48,56,64,80,96,112,128,144,160,0},{0,32,40,48,56,64,80,96,112,128,144,160,176,192,224,0}};int row=layer==1?0:layer==2?1:2;return version==1?m1[row,index]:m2[row,index];}
 static int Rate(int version,int index){int[] a={44100,48000,32000,0};int r=a[index];if(version==2)r/=2;else if(version==25)r/=4;return r;}
 static int DolbyBits(byte[] b,ref int bit,int n){if(bit+n>b.Length*8)throw new System.IO.EndOfStreamException("Truncated Dolby syncframe header");int v=0;for(int i=0;i<n;i++){v=(v<<1)|((b[bit>>3]>>(7-(bit&7)))&1);bit++;}return v;}
 static int DolbyBaseChannels(int m){int[] c={2,1,2,3,3,4,4,5};return c[m&7];} static string DolbyLayoutName(int n){if(n==1)return "mono";if(n==2)return "stereo";if(n==6)return "5.1";if(n==8)return "7.1";return n+" channels";}
 static void Ac3(byte[] b,int p,int avail,CanonicalAudioAnalysisResult r,out int size){int bit=(p+4)*8;int f=DolbyBits(b,ref bit,2),fc=DolbyBits(b,ref bit,6),bsid=DolbyBits(b,ref bit,5);if(bsid>10)throw new System.IO.InvalidDataException("Not legacy AC-3");DolbyBits(b,ref bit,3);int acmod=DolbyBits(b,ref bit,3);if((acmod&1)!=0&&acmod!=1)DolbyBits(b,ref bit,2);if((acmod&4)!=0)DolbyBits(b,ref bit,2);if(acmod==2)DolbyBits(b,ref bit,2);bool lfe=DolbyBits(b,ref bit,1)!=0;int[] hzv={48000,44100,32000,0};int[] kv={32,40,48,56,64,80,96,112,128,160,192,224,256,320,384,448,512,576,640};int hz=hzv[f],code=fc>>1;if(hz==0||code>=kv.Length)throw new System.IO.InvalidDataException("Invalid AC-3 header");int kb=kv[code];if(hz==48000)size=kb*4;else if(hz==32000)size=kb*6;else{int[] w={69,87,104,121,139,174,208,243,278,348,417,487,557,696,835,975,1114,1253,1393};size=(w[code]+(fc&1))*2;}if(size>avail)throw new System.IO.EndOfStreamException("AC-3 syncframe exceeds sample");int ch=DolbyBaseChannels(acmod)+(lfe?1:0);r.DolbyPcmSamples+=1536;r.DolbyCodec="Dolby Digital / AC-3";r.DolbySampleRate=hz;r.DolbyChannels=ch;r.DolbyLayout=DolbyLayoutName(ch);}
 static void Eac3(byte[] b,int p,int avail,CanonicalAudioAnalysisResult r,out int size){int bit=(p+2)*8;DolbyBits(b,ref bit,2);DolbyBits(b,ref bit,3);size=(DolbyBits(b,ref bit,11)+1)*2;if(size>avail)throw new System.IO.EndOfStreamException("E-AC-3 syncframe exceeds sample");int f=DolbyBits(b,ref bit,2),hz,blocks;if(f==3){int f2=DolbyBits(b,ref bit,2);int[] h={24000,22050,16000,0};hz=h[f2];blocks=6;}else{int[] h={48000,44100,32000};hz=h[f];int[] bl={1,2,3,6};blocks=bl[DolbyBits(b,ref bit,2)];}int acmod=DolbyBits(b,ref bit,3);bool lfe=DolbyBits(b,ref bit,1)!=0;int bsid=DolbyBits(b,ref bit,5);if(bsid<=10)throw new System.IO.InvalidDataException("Not E-AC-3");int kb=(int)Math.Round(size*8.0*hz/(blocks*256.0)/1000.0);int ch=DolbyBaseChannels(acmod)+(lfe?1:0);r.DolbyPcmSamples+=(long)blocks*256;r.DolbyCodec="Dolby Digital Plus / E-AC-3";r.DolbySampleRate=hz;r.DolbyChannels=ch;r.DolbyLayout=DolbyLayoutName(ch);}
 static void ParseDolby(System.IO.FileStream fs,LsdSampleModel sample,CanonicalAudioAnalysisResult r){byte[] b=new byte[(int)sample.Length];fs.Position=sample.FileOffset;int o=0,n;while(o<b.Length&&(n=fs.Read(b,o,b.Length-o))>0)o+=n;if(o!=b.Length)throw new System.IO.EndOfStreamException("Truncated Dolby sample");int p=0,found=0;while(p+8<=b.Length){if(b[p]!=0x0B||b[p+1]!=0x77){p++;continue;}int size;try{int bsid=(b[p+5]>>3)&31;if(bsid<=10)Ac3(b,p,b.Length-p,r,out size);else Eac3(b,p,b.Length-p,r,out size);found++;r.DolbyFrames++;r.DolbyBytes+=size;p+=size;}catch(Exception){r.DolbyRejected++;throw;}}if(found==0)throw new System.IO.InvalidDataException("No Dolby syncframe found");}
 static void ParseMp3(System.IO.FileStream fs,LsdSampleModel sample,CanonicalAudioAnalysisResult r){byte[] b=new byte[(int)sample.Length];fs.Position=sample.FileOffset;int o=0,n;while(o<b.Length&&(n=fs.Read(b,o,b.Length-o))>0)o+=n;if(o!=b.Length)throw new System.IO.EndOfStreamException("Truncated MPEG Audio sample");int p=0,found=0;while(p+4<=b.Length){if(b[p]!=0xFF||(b[p+1]&0xE0)!=0xE0){p++;continue;}int vb=(b[p+1]>>3)&3,lb=(b[p+1]>>1)&3,bi=(b[p+2]>>4)&15,ri=(b[p+2]>>2)&3,pad=(b[p+2]>>1)&1;if(vb==1||lb==0||bi==0||bi==15||ri==3){p++;continue;}int version=vb==3?1:vb==2?2:25;int layer=4-lb;int kb=Bitrate(version,layer,bi),hz=Rate(version,ri);int size=layer==1?((12*kb*1000/hz)+pad)*4:(layer==3&&version!=1?72:144)*kb*1000/hz+pad;if(size<4||p+size>b.Length){p++;continue;}found++;r.MpegAudioFrames++;r.MpegAudioBytes+=size;r.MpegAudioPcmSamples+=layer==1?384:(layer==3&&version!=1?576:1152);r.MpegVersion=version;r.Layer=layer;r.SampleRate=hz;r.Channels=((b[p+3]>>6)&3)==3?1:2;if(kb<r.MinimumFrameBitrate)r.MinimumFrameBitrate=kb;if(kb>r.MaximumFrameBitrate)r.MaximumFrameBitrate=kb;p+=size;}if(found==0)throw new System.IO.InvalidDataException("No valid MPEG Audio frame header was found");}
 public static CanonicalAudioAnalysisResult Analyze(string path,LsdTrackModel track,double duration){var r=new CanonicalAudioAnalysisResult();if(track==null)return r;r.CodecFamily=track.CodecFamily;r.PayloadFormat=track.PayloadFormat;r.DurationSeconds=duration;using(var fs=new System.IO.FileStream(path,System.IO.FileMode.Open,System.IO.FileAccess.Read,System.IO.FileShare.ReadWrite)){foreach(var s in track.Samples){try{if(s.FileOffset<0||s.Length<=0||s.FileOffset+s.Length>fs.Length)throw new System.IO.InvalidDataException("Canonical audio sample is outside file bounds");r.Samples++;r.PayloadBytes+=s.Length;if(s.Length<r.Minimum)r.Minimum=s.Length;if(s.Length>r.Maximum)r.Maximum=s.Length;if(track.CodecFamily=="MP3")ParseMp3(fs,s,r);else if(track.CodecFamily=="AC3"||track.CodecFamily=="EAC3")ParseDolby(fs,s,r);else if(track.CodecFamily=="PCM"){if(track.PcmBlockAlign<=0||track.PcmBitDepth<=0||track.Channels<=0||track.SamplingRate<=0)throw new System.IO.InvalidDataException("Incomplete PCM format parameters");if((s.Length%track.PcmBlockAlign)!=0)throw new System.IO.InvalidDataException("PCM sample is not block aligned");r.PcmBitDepth=track.PcmBitDepth;r.PcmBlockAlign=track.PcmBlockAlign;r.PcmChannels=(int)track.Channels;r.PcmSampleRate=(int)track.SamplingRate;r.PcmFloat=track.PcmFloat;r.PcmBigEndian=track.PcmBigEndian;r.PcmFormat=(track.PcmFloat?"floating-point":"signed integer")+", "+track.PcmBitDepth+"-bit "+(track.PcmBigEndian?"big-endian":"little-endian");}}catch(Exception ex){r.Rejected++;if(r.FirstError.Length==0)r.FirstError=ex.GetType().Name+": "+ex.Message;}}}if(r.Samples>0){r.Average=(double)r.PayloadBytes/r.Samples;if(duration>0)r.Bitrate=r.PayloadBytes*8.0/duration;if(r.MpegAudioPcmSamples>0&&r.SampleRate>0)r.Bitrate=r.MpegAudioBytes*8.0/((double)r.MpegAudioPcmSamples/r.SampleRate);if(r.DolbyPcmSamples>0&&r.DolbySampleRate>0)r.Bitrate=r.DolbyBytes*8.0/((double)r.DolbyPcmSamples/r.DolbySampleRate);if(r.CodecFamily=="PCM"&&r.PcmBlockAlign>0&&r.PcmSampleRate>0){r.PcmDecodedDuration=(double)r.PayloadBytes/(r.PcmBlockAlign*r.PcmSampleRate);r.Bitrate=(double)r.PcmSampleRate*r.PcmBitDepth*r.PcmChannels;}}if(r.Minimum==Int64.MaxValue)r.Minimum=0;if(r.MinimumFrameBitrate==Int32.MaxValue)r.MinimumFrameBitrate=0;return r;}
}

public sealed class Av1CodecConfigurationResult {
