public sealed class NativeAviPreparationJob : IDisposable {
 System.Threading.Thread thread; volatile bool done,cancelled; string error=""; AviProbeResult probe; LsdMediaModel media;
 public bool Done{get{return done;}} public bool Cancelled{get{return cancelled;}} public string Error{get{return error;}} public AviProbeResult Probe{get{return probe;}} public LsdMediaModel Media{get{return media;}}
 public void Start(string path){thread=new System.Threading.Thread(()=>Run(path));thread.IsBackground=true;thread.Name="LSD AVI index preparation";thread.Start();}
 void Run(string path){try{if(cancelled)return;var p=NativeAviProbe.Inspect(path);if(cancelled)return;var m=NativeAviProbe.Adapt(path,p);if(cancelled)return;probe=p;media=m;}catch(Exception ex){error=ex.ToString();}finally{done=true;}}
 public void Cancel(){cancelled=true;} public void Dispose(){cancelled=true;if(thread!=null&&thread.IsAlive)thread.Join(250);}
}

public sealed class NativeMp4PreparationJob : IDisposable {
