public sealed class Vp9BitReader {
 readonly byte[] data; readonly int end; int bit;
 public Vp9BitReader(byte[] d,int offset,int length){if(d==null)throw new ArgumentNullException("d");if(offset<0||length<=0||offset+length>d.Length)throw new ArgumentOutOfRangeException();data=d;bit=offset*8;end=(offset+length)*8;}
