 public int ReadBits(int n){if(n<0||n>32||end-bit<n)throw new System.IO.EndOfStreamException("VP9 uncompressed header ended");int v=0;while(n-->0)v=(v<<1)|ReadBit();return v;}
 public int ReadSigned(int n){int v=ReadBits(n);return ReadBit()!=0?-v:v;}
}
public sealed class Vp9FrameParser {
 sealed class RefState { public int Width,Height,Type; }
 readonly RefState[] refs=new RefState[8];
 static void Sync(Vp9BitReader b){if(b.ReadBits(24)!=0x498342)throw new System.IO.InvalidDataException("Invalid VP9 frame sync code");}
 static void Color(Vp9BitReader b,int profile){if(profile>=2)b.ReadBit();int cs=b.ReadBits(3);if(cs!=7){b.ReadBit();if(profile==1||profile==3){b.ReadBit();b.ReadBit();if(b.ReadBit()!=0)throw new System.IO.InvalidDataException("Invalid VP9 reserved color bit");}}else{if(profile!=1&&profile!=3)throw new System.IO.InvalidDataException("VP9 RGB is not valid in this profile");if(b.ReadBit()!=0)throw new System.IO.InvalidDataException("Invalid VP9 RGB reserved bit");}}
