 var counts=new System.Collections.Generic.SortedDictionary<int,long>();foreach(var e in r.Index){if(!counts.ContainsKey(e.NalType))counts[e.NalType]=0;counts[e.NalType]++;}var text=new StringBuilder();foreach(var kv in counts){if(text.Length>0)text.Append(", ");text.Append(Names(kv.Key)).Append(':').Append(kv.Value);}r.NalInventory=text.ToString();r.Validation=r.FirstError.Length==0&&r.ConfigFirstError.Length==0&&r.SpsFirstError.Length==0&&r.PpsFirstError.Length==0&&r.PhFirstError.Length==0&&r.ConfigSps>0&&r.ConfigPps>0&&r.ContextValidation=="PASS"&&r.ResolvedPictures==r.Samples&&r.PhPrefixesParsed==r.Vcl&&r.PhPrefixesRejected==0&&r.PhPpsMismatch==0&&r.PhNalClassMismatch==0?"PASS":"INCOMPLETE";return r;}
}
