 static readonly int[,] AreaScale=new int[2,31]{{4,4,4,4,4,4,4,4,4,4,4,4,4,4,8,8,8,8,16,16,16,16,4,4,4,4,4,4,4,4,4},{4,4,4,4,4,4,4,4,4,4,4,4,4,4,16,16,16,16,32,32,32,32,4,4,4,4,4,4,4,4,4}};
 static int Level(int v){return v>=0&&v<31?v:30;} static int Tier(int v){return v==1?1:0;}
