public sealed class Av2ReferenceStateBank {
 readonly Av2ReferenceSlotState[] slots=new Av2ReferenceSlotState[8];
 public Av2ReferenceStateBank(){for(int i=0;i<slots.Length;i++)slots[i]=new Av2ReferenceSlotState{Slot=i};}
 public int ValidCount{get{int n=0;for(int i=0;i<slots.Length;i++)if(slots[i].Valid)n++;return n;}} public bool IsValid(int slot){return slot>=0&&slot<slots.Length&&slots[slot].Valid;} public int GetOrderHint(int slot){if(!IsValid(slot))throw new ArgumentOutOfRangeException("slot");return slots[slot].OrderHint;} public int GetBaseQIdx(int slot){if(!IsValid(slot))throw new ArgumentOutOfRangeException("slot");return slots[slot].BaseQIdx;} public int GetFrameWidth(int slot){if(!IsValid(slot))throw new ArgumentOutOfRangeException("slot");return slots[slot].FrameWidth;} public int GetFrameHeight(int slot){if(!IsValid(slot))throw new ArgumentOutOfRangeException("slot");return slots[slot].FrameHeight;}
