  if(prefix==null||!prefix.Complete)throw new ArgumentException("AV2 CLK prefix is incomplete");if(frame==null||!frame.Complete)throw new ArgumentException("AV2 CLK frame size is incomplete");if(quant==null||!quant.Complete)throw new ArgumentException("AV2 CLK quantization is incomplete");
  var r=new Av2ReferenceStateInitResult{RefreshFlags=prefix.RefreshFrameFlags};if(r.RefreshFlags<0||r.RefreshFlags>255)throw new System.IO.InvalidDataException("AV2 CLK refresh flags are invalid");
  for(int i=0;i<slots.Length;i++){if((r.RefreshFlags&(1<<i))==0)continue;var x=slots[i];x.Valid=true;x.FrameWidth=frame.FrameWidth;x.FrameHeight=frame.FrameHeight;x.OrderHint=prefix.OrderHint;x.BaseQIdx=quant.BaseQIdx;x.FrameType=0;r.SlotsUpdated++;}
  for(int i=0;i<slots.Length;i++)if(slots[i].Valid)r.ValidSlots++;r.Complete=true;r.StopReason="RegularFramePrefixTraversalRequired";return r;
 }
}

