function Add-CanonicalReportRows($report,[object[]]$rows){
    foreach($item in $rows){
        $line=[string]$item
        if($line-match'^\[ (.+) \]$'){
            $report.NextSectionOrder+=100
            $id=($Matches[1].ToLowerInvariant()-replace'[^a-z0-9]+','-').Trim('-')
            $report.CurrentSection=Add-CanonicalSummarySection $report $id $line $report.NextSectionOrder
            $report.NextRowOrder=0
            continue
        }
        if($null-eq$report.CurrentSection){
            $report.NextSectionOrder+=100
            $report.CurrentSection=Add-CanonicalSummarySection $report 'preamble' '' $report.NextSectionOrder
            $report.NextRowOrder=0
        }
        $report.NextRowOrder+=10
        if($line-match'^([^:]{2,35}:)\s*(.*)$'-and$line-notmatch'^Track\s+\d+:'){
            Add-CanonicalSummaryRow $report.CurrentSection ($report.CurrentSection.Id+'.'+$report.NextRowOrder) $Matches[1].TrimEnd(':') $Matches[2] $line $report.NextRowOrder 'Value'
        }else{
            Add-CanonicalSummaryRow $report.CurrentSection ($report.CurrentSection.Id+'.'+$report.NextRowOrder) '' '' $line $report.NextRowOrder 'Literal'
        }
    }
}
