        'Total pictures'='hevc.frames.total';'VCL NAL units'='hevc.frames.vcl_nal_units';'IRAP pictures'='hevc.frames.irap';'IDR / CRA / BLA'='hevc.frames.idr_cra_bla';'TRAIL / RADL / RASL'='hevc.frames.trail_radl_rasl';'Key frames'='hevc.frames.key';'GOP length'='hevc.frames.gop';'Packet/frame match'='hevc.frames.packet_match';'I-pictures'='hevc.frames.i';'P-pictures'='hevc.frames.p';'B-pictures'='hevc.frames.b';'Other pictures'='hevc.frames.other';'Slice headers'='hevc.frames.slice_headers';'Native suffix consistency'='hevc.frames.suffix_consistency';'All-suffix failure'='hevc.frames.first_suffix_failure';'HEVC I/P/B validation'='hevc.frames.ipb_validation'
    }
    Set-CsrSectionKeys $report 'native-hevc-stream-analysis' $hevcStream 'hevc.stream.literal' $true
    $hevcQp=@{
        'PPS initial QP'='hevc.qp.pps_initial';'CU QP delta'='hevc.qp.cu_delta';'Weighted prediction'='hevc.qp.weighted_prediction';'Tiles / WPP'='hevc.qp.tiles_wpp';'SliceQPY output'='hevc.qp.output';'Safety mode'='hevc.qp.safety_mode'
    }
    Set-CsrSectionKeys $report 'hevc-qp-analysis' $hevcQp 'hevc.qp.literal' $true
    $hevcValidation=@{
        'Headers parsed'='hevc.validation.headers_parsed';'Headers rejected'='hevc.validation.headers_rejected';'I parsed/rejected'='hevc.validation.i_parsed_rejected';'P parsed/rejected'='hevc.validation.p_parsed_rejected';'B parsed/rejected'='hevc.validation.b_parsed_rejected';'Failures EOF/align/QP'='hevc.validation.failures_eof_align_qp';'Failures list/mark/other'='hevc.validation.failures_list_mark_other';'First failure'='hevc.validation.first_failure';'SliceQPY average'='hevc.quantizer.average';'SliceQPY range'='hevc.quantizer.range';'Validated'='hevc.validation.result'
    }
    Set-CsrSectionKeys $report 'hevc-qp-validation' $hevcValidation 'hevc.validation.literal' $true
    $hevcQuant=@{
        'Values / frames'='hevc.quantizer.values_frames';'Average DRF'='hevc.quantizer.average_drf';'Standard deviation'='hevc.quantizer.stddev';'Minimum / maximum'='hevc.quantizer.min_max';'I-slice QP average'='hevc.quantizer.i_average';'P-slice QP average'='hevc.quantizer.p_average';'B-slice QP average'='hevc.quantizer.b_average';'I/P/B std. deviation'='hevc.quantizer.ipb_stddev';'Native QP count'='hevc.quantizer.native_count';'Native QP completeness'='hevc.quantizer.completeness';'Histogram source'='hevc.quantizer.histogram_source';'External dependency'='hevc.quantizer.external_dependency';'Validation note'='hevc.quantizer.validation_note'
    }
    Set-CsrSectionKeys $report 'hevc-drf-qp-analysis' $hevcQuant 'hevc.quantizer.literal' $true
    $quant=@($report.Sections|Where-Object{$_.Id-eq'quantizer-analysis'});if($quant.Count-eq1){$i=0;foreach($row in @($quant[0].Rows|Sort-Object Order)){$i++;$row.Key='quantizer.summary.'+$i}}
}
function ConvertTo-CsrKeyPart([string]$text){
    $key=($text.ToLowerInvariant()-replace'[^a-z0-9]+','_').Trim('_')
    if([string]::IsNullOrWhiteSpace($key)){return 'value'}
    return $key
}
function Set-CsrNamespacedSectionKeys($report,[string]$sectionId,[string]$namespace,[bool]$optional){
    $found=@($report.Sections|Where-Object{$_.Id-eq$sectionId})
    if($found.Count-eq0){if($optional){return};throw('CSR section missing: '+$sectionId)}
    if($found.Count-ne1){throw('CSR section ambiguous: '+$sectionId)}
    $seen=@{};$literal=0
    foreach($row in @($found[0].Rows|Sort-Object Order)){
        if($row.Kind-eq'Value'){
            $part=ConvertTo-CsrKeyPart ([string]$row.Label)
            $base=$namespace+'.'+$part
            if($seen.ContainsKey($base)){$seen[$base]++;$row.Key=$base+'.'+$seen[$base]}else{$seen[$base]=1;$row.Key=$base}
        }else{$literal++;$row.Key=$namespace+'.literal.'+$literal}
    }
}
function Set-CanonicalRemainingCodecSections($report){
    $sections=@{
        'native-vvc-two-pass-analysis'='vvc.analysis'
        'native-av1-configuration'='av1.configuration'
        'native-av1-sequence-header'='av1.sequence'
        'native-av1-sample-obu-analysis'='av1.obu'
        'native-av1-frame-analysis'='av1.frames'
        'native-av1-frame-state'='av1.state'
        'native-av1-reference-geometry'='av1.geometry'
        'native-av1-base-q-index-analysis'='av1.quantizer'
        'native-av2-sample-obu-analysis'='av2.obu'
        'native-av2-frame-analysis'='av2.frames'
        'native-av2-reference-geometry'='av2.geometry'
        'native-av2-base-q-index-analysis'='av2.quantizer'
        'native-vp8-frame-base-q-analysis'='vp8.analysis'
        'native-vp9-frame-base-q-analysis'='vp9.analysis'
        'native-mpeg-4-part-2-analysis'='mpeg4.analysis'
        'native-mp4-sample-index'='mp4.sample_index'
        'native-avi-sample-index'='avi.sample_index'
        'native-mpeg-audio-analysis'='audio.mpeg'
        'native-dolby-audio-analysis'='audio.dolby'
        'native-pcm-audio-analysis'='audio.pcm'
        'subtitles'='subtitles'
    }
    foreach($sectionId in $sections.Keys){Set-CsrNamespacedSectionKeys $report $sectionId ([string]$sections[$sectionId]) $true}
    Set-CsrNamespacedSectionKeys $report 'quantizer-analysis' 'quantizer.summary' $true
}
function Copy-CanonicalSummaryReport($source){if($null-eq$source){return $null};$copy=New-CanonicalSummaryReport;foreach($ss in @($source.Sections|Sort-Object Order)){$ts=Add-CanonicalSummarySection $copy ([string]$ss.Id) ([string]$ss.Title) ([int]$ss.Order);foreach($sr in @($ss.Rows|Sort-Object Order)){Add-CanonicalSummaryRow $ts ([string]$sr.Key) ([string]$sr.Label) ([string]$sr.DisplayValue) ([string]$sr.RawText) ([int]$sr.Order) ([string]$sr.Kind)}};return $copy}
function ConvertTo-EncodeSummaryReport($source){
    $target=New-CanonicalSummaryReport
    foreach($section in @($source.Sections|Sort-Object Order)){
        if($section.Id-ne'native-vvc-two-pass-analysis'){
            $out=Add-CanonicalSummarySection $target ([string]$section.Id) ([string]$section.Title) ([int]$section.Order)
            foreach($row in @($section.Rows|Sort-Object Order)){Add-CanonicalSummaryRow $out ([string]$row.Key) ([string]$row.Label) ([string]$row.DisplayValue) ([string]$row.RawText) ([int]$row.Order) ([string]$row.Kind)}
            continue
        }
        $out=Add-CanonicalSummarySection $target 'native-vvc-frame-analysis' '[ Native VVC Frame Analysis ]' ([int]$section.Order)
        $wanted=@('Pass 1 - indexed samples','Pass 1 - indexed NAL units','VCL / IRAP','IDR / CRA / GDR','Pass 2 - resolved pictures','Pass 2 - unresolved samples','SH slice types I / P / B','SliceQPY parsed/rejected','SliceQPY range / average','First SliceQPY failure','Two-pass structural validation','I/P/B and SliceQPY')
        $order=0
        foreach($label in $wanted){
            $row=@($section.Rows|Where-Object{$_.Kind-eq'Value'-and$_.Label-eq$label}|Select-Object -First 1)
            if($row.Count){$order+=10;Add-CanonicalSummaryRow $out ('vvc.summary.'+(ConvertTo-CsrKeyPart $label)) $label ([string]$row[0].DisplayValue) ([string]$row[0].RawText) $order 'Value'}
        }
    }
    return $target
}
function Render-CanonicalSummaryReport($report){$a=New-Object Collections.Generic.List[string];foreach($s in @($report.Sections|Sort-Object Order)){if($s.Title){$a.Add([string]$s.Title)};foreach($r in @($s.Rows|Sort-Object Order)){if($r.Kind-eq'Value'){$a.Add(("{0,-35} {1}"-f($r.Label+':'),$r.DisplayValue))}else{$a.Add([string]$r.RawText)}}};return $a.ToArray()}
function Test-CanonicalRenderedEquality([string[]]$x,[string[]]$y){if($x.Count-ne$y.Count){return $false};for($i=0;$i-lt$x.Count;$i++){if([string]$x[$i]-cne[string]$y[$i]){return $false}};return $true}
function Render {
    if($null -eq $script:Meta) { $summary.Clear(); return }
    $fmt=$script:Meta.format
    $streams=@($script:Meta.streams)
    $video=@($streams | Where-Object { $_.codec_type -eq 'video' })[0]
    $audios=@($streams | Where-Object { $_.codec_type -eq 'audio' })
    $subs=@($streams | Where-Object { $_.codec_type -eq 'subtitle' })
    $fi=Get-Item -LiteralPath $script:File
    $mux=if($fmt.tags.muxing_application){$fmt.tags.muxing_application}elseif($fmt.tags.ENCODER){$fmt.tags.ENCODER}else{'N/A'}
    $writer=if($fmt.tags.writing_application){$fmt.tags.writing_application}else{'N/A'}
    $nativeContainer=if($script:NativeInfo){$script:NativeInfo.Container}else{'N/A'};$nativeDocType=if($script:NativeInfo -and $script:NativeInfo.DocType){$script:NativeInfo.DocType}else{'N/A'};$nativeTrackCount=if($script:NativeInfo){$script:NativeInfo.Tracks.Count}else{0}
    $canonicalReport=New-CanonicalSummaryReport
    Add-CanonicalReportRows $canonicalReport @('[ File ]','',"Name:               $($fi.Name)","Modified:           $($fi.LastWriteTime.ToString('yyyy-MM-dd HH:mm:ss'))","Size:               $('{0:N0}' -f $fi.Length) bytes ($(Bytes $fi.Length))","Duration:           $(Dur $fmt.duration)","Container:          $(NA $fmt.format_long_name)","Native detection:   $nativeContainer","Native DocType:     $nativeDocType","Native tracks:      $nativeTrackCount","Tracks:             $($streams.Count) (video $(@($streams|Where-Object{$_.codec_type -eq 'video'}).Count), audio $($audios.Count), subtitles $($subs.Count))","Muxing library:     $mux","Writing application: $writer")
    if($script:NativeInfo -and $script:NativeInfo.Tracks.Count -gt 0){Add-CanonicalReportRows $canonicalReport @('','[ Native Container Tracks ]','');foreach($nt in $script:NativeInfo.Tracks){$detail=if($nt.Kind -eq 'video'){"$($nt.Width) x $($nt.Height)"}elseif($nt.Kind -eq 'audio'){if($nt.OutputSampleRate -gt 0){"core $($nt.CoreSampleRate) Hz / $($nt.CoreAudioChannels) ch, output $($nt.OutputSampleRate) Hz / $($nt.AudioChannels) ch"}else{"$($nt.SamplingRate) Hz, $($nt.Channels) ch"}}else{''};Add-CanonicalReportRows $canonicalReport ("Track {0}: {1} | {2} | {3} | {4}" -f $nt.Number,$nt.Kind,$nt.CodecId,$nt.Language,$detail)}}
    if($script:ReadyMedia){Add-CanonicalReportRows $canonicalReport @('','[ LSD 3.0 Canonical Model ]','',('Status:                {0}' -f $script:ReadyModelStatus),('Adapter:               {0}' -f $script:ReadyMedia.AdapterName),('Canonical tracks:      {0} (video {1}, audio {2}, subtitle {3})' -f $script:ReadyMedia.Tracks.Count,$script:ReadyMedia.CountType('video'),$script:ReadyMedia.CountType('audio'),$script:ReadyMedia.CountType('subtitle')),'Routing:               Canonical media pipeline active','Sample model:          Active canonical video and audio sample indexes')}
    if($script:ReadyMedia -and $script:NativeInfo.Container -eq 'AVI') {
        $aviVideo=@($script:ReadyMedia.Tracks | Where-Object { $_.TrackType -eq 'video' } | Select-Object -First 1)
        Add-CanonicalReportRows $canonicalReport @('','[ Native AVI Sample Index ]','',('Video samples:         {0:N0}' -f $(if($aviVideo){$aviVideo.Samples.Count}else{0})),('Index mode:            {0}' -f $script:AviProbe.IndexMode),('OpenDML AVI:           {0}' -f $(if($script:AviProbe.OpenDml){'Yes'}else{'No'})),('RIFF / AVIX segments:  {0} / {1}' -f $script:AviProbe.RiffSegments,$script:AviProbe.AvixSegments),('Standard indexes:      {0}' -f $script:AviProbe.StandardIndexes),('Legacy idx1:           {0}' -f $(if($script:AviProbe.LegacyIndexPresent){'Present'}else{'Not present'})),'Video mapping:         XVID/DIVX/DX50/FMP4/MP4V => MPEG-4 Part 2 ASP; H264/X264/AVC1/DAVC => AVC Annex B')
    }
    if($script:ReadyMedia -and $script:NativeInfo.Container -eq 'MP4 / MOV') {
        $mp4Video=@($script:ReadyMedia.Tracks | Where-Object { $_.TrackType -eq 'video' } | Select-Object -First 1)
        $mp4SampleCount=if($mp4Video){$mp4Video.Samples.Count}else{0}
        Add-CanonicalReportRows $canonicalReport @('','[ Native MP4 Sample Index ]','',('Video samples:         {0:N0}' -f $mp4SampleCount),('Timecode scale:        {0:N0} ns/tick' -f $script:ReadyMedia.TimecodeScale),$(if($script:Mp4Probe -and $script:Mp4Probe.Fragmented){'Sample index mode:     moof + traf + tfhd + tfdt + trun'}else{'Sample index mode:     stsc + stsz + stco/co64 + stts/ctts + stss'}),$(if($nativeVideo -and $nativeVideo.CodecId -eq 'V_AV1'){'AV1 sample entry:     av01 + av1C'}elseif(@($script:NativeInfo.Tracks|Where-Object{$_.CodecId -eq 'A_AC3'}).Count){'Audio sample entry:   ac-3 + dac3'}elseif(@($script:NativeInfo.Tracks|Where-Object{$_.CodecId -eq 'A_EAC3'}).Count){'Audio sample entry:   ec-3 + dec3'}elseif(@($script:NativeInfo.Tracks|Where-Object{$_.CodecId -eq 'A_MPEG/L3'}).Count){'Audio sample entry:   MP3 / MPEG Audio'}elseif(@($script:NativeInfo.Tracks|Where-Object{$_.CodecId -eq 'A_PCM'}).Count){'Audio sample entry:   PCM / LPCM'}else{'Codec configuration:  native MP4 sample entry'}),$(if($script:Mp4Probe -and $script:Mp4Probe.Fragmented){'Fragmented MP4:        Supported - moof/traf/tfhd/tfdt/trun'}else{'Fragmented MP4:        Not detected'}))
    }


    if($script:NativeInfo){
        $nativeVideo=@($script:NativeInfo.Tracks|Where-Object{$_.Kind -eq 'video'})[0]
        $script:HevcHvccProbe=$null
        if($nativeVideo -and $nativeVideo.CodecId -eq 'V_MPEGH/ISO/HEVC' -and $nativeVideo.CodecPrivate){
            try {
                $script:HevcHvccProbe=[HevcHvccContextProbe]::Parse([byte[]]$nativeVideo.CodecPrivate)
            } catch {
                $script:HevcHvccProbe=$null
            }
        }
        if($nativeVideo -and $nativeVideo.CodecPrivate){
            if($nativeVideo.CodecId -eq 'V_AV1'){
                Add-CanonicalReportRows $canonicalReport @('','[ Native AV1 Configuration ]','',"CodecPrivate size:   $($nativeVideo.CodecPrivate.Length) bytes","Configuration:      AV1CodecConfigurationRecord","Marker / version:   $($nativeVideo.Av1Marker) / $($nativeVideo.Av1Version)","Profile:            $($nativeVideo.Profile) ($($nativeVideo.Av1Profile))","Level index / tier: $($nativeVideo.Av1Level) / $(if($nativeVideo.Av1Tier){'High'}else{'Main'})","Bit depth:          $($nativeVideo.BitDepth) bit","Monochrome:         $(if($nativeVideo.Av1Monochrome){'Yes'}else{'No'})","Chroma format:      $($nativeVideo.Chroma)","Chroma subsampling: $($nativeVideo.Av1SubsamplingX) / $($nativeVideo.Av1SubsamplingY)","Chroma sample pos.: $($nativeVideo.Av1ChromaSamplePosition)","Initial delay:      $(if($nativeVideo.Av1InitialPresentationDelayMinusOne -ge 0){$nativeVideo.Av1InitialPresentationDelayMinusOne+1}else{'Not present'})","Config OBU bytes:   $($nativeVideo.Av1ConfigObuBytes)","Config OBU count:   $($nativeVideo.Av1ConfigObuCount)","Sequence headers:   $($nativeVideo.Av1SequenceHeaderObuCount)","OBU inventory:      $(if($nativeVideo.Av1ObuInventory){$nativeVideo.Av1ObuInventory}else{'None'})","Configuration validation: $(if($nativeVideo.Av1ConfigValid -and $nativeVideo.Av1SequenceHeaderObuCount -gt 0){'PASS'}else{'INCOMPLETE'})")
                Add-CanonicalReportRows $canonicalReport @('','[ Native AV1 Sequence Header ]','',"Maximum frame size: $($nativeVideo.Av1MaxFrameWidth) x $($nativeVideo.Av1MaxFrameHeight)","Dimension bits W/H: $($nativeVideo.Av1FrameWidthBits) / $($nativeVideo.Av1FrameHeightBits)","Still picture:      $(if($nativeVideo.Av1StillPicture){'Yes'}else{'No'})","Reduced header:     $(if($nativeVideo.Av1ReducedStillPictureHeader){'Yes'}else{'No'})","Timing info:        $(if($nativeVideo.Av1TimingInfoPresent){'Present'}else{'Not present'})","Operating points:   $($nativeVideo.Av1OperatingPoints)","Frame IDs:          $(if($nativeVideo.Av1FrameIdNumbersPresent){'Present'}else{'Not present'})","128x128 superblock: $(if($nativeVideo.Av1Use128x128Superblock){'Yes'}else{'No'})","Filter intra:       $(if($nativeVideo.Av1EnableFilterIntra){'Enabled'}else{'Disabled'})","Intra edge filter:  $(if($nativeVideo.Av1EnableIntraEdgeFilter){'Enabled'}else{'Disabled'})","Interintra compound: $(if($nativeVideo.Av1EnableInterintraCompound){'Enabled'}else{'Disabled'})","Masked compound:    $(if($nativeVideo.Av1EnableMaskedCompound){'Enabled'}else{'Disabled'})","Warped motion:      $(if($nativeVideo.Av1EnableWarpedMotion){'Enabled'}else{'Disabled'})","Dual filter:        $(if($nativeVideo.Av1EnableDualFilter){'Enabled'}else{'Disabled'})","Order hint:         $(if($nativeVideo.Av1EnableOrderHint){'Enabled, {0} bits' -f $nativeVideo.Av1OrderHintBits}else{'Disabled'})","Screen content tools: $(switch($nativeVideo.Av1ForceScreenContentTools){2{'Per-frame selectable'}1{'Forced on'}default{'Disabled'}})","Integer MV mode:    $(switch($nativeVideo.Av1ForceIntegerMv){2{'Per-frame selectable'}1{'Forced on'}default{'Disabled'}})","Joint compound:     $(if($nativeVideo.Av1EnableJntComp){'Enabled'}else{'Disabled'})","Reference frame MVs: $(if($nativeVideo.Av1EnableRefFrameMvs){'Enabled'}else{'Disabled'})","Super-resolution:   $(if($nativeVideo.Av1EnableSuperres){'Enabled'}else{'Disabled'})","CDEF:               $(if($nativeVideo.Av1EnableCdef){'Enabled'}else{'Disabled'})","Loop restoration:   $(if($nativeVideo.Av1EnableRestoration){'Enabled'}else{'Disabled'})","Color description:  $(if($nativeVideo.Av1ColorDescriptionPresent){'Present'}else{'Unspecified defaults'})","Color P/T/M:        $($nativeVideo.Av1ColorPrimaries) / $($nativeVideo.Av1TransferCharacteristics) / $($nativeVideo.Av1MatrixCoefficients)","Color range:        $(if($nativeVideo.Av1ColorRange){'Full'}else{'Limited'})","Separate UV delta Q: $(if($nativeVideo.Av1SeparateUvDeltaQ){'Yes'}else{'No'})","Film grain params:  $(if($nativeVideo.Av1FilmGrainParamsPresent){'Present'}else{'Not present'})","Sequence bits read: $($nativeVideo.Av1SequenceBits)","Sequence/header match: $(if($nativeVideo.Av1SequenceValid -and $nativeVideo.Av1MaxFrameWidth -eq $nativeVideo.Width -and $nativeVideo.Av1MaxFrameHeight -eq $nativeVideo.Height){'PASS'}else{'CHECK'})")
            } elseif($nativeVideo.CodecId -eq 'V_MPEGH/ISO/HEVC'){
                Add-CanonicalReportRows $canonicalReport @('','[ Native HEVC Configuration ]','',"NAL length size:     $($nativeVideo.NalLengthSize) bytes","Profile / Tier:     $(NA $nativeVideo.Profile) / $(if($nativeVideo.HevcTier){'High'}else{'Main'})","Level:              $(if($nativeVideo.HevcLevel -gt 0){'{0:N1}' -f ($nativeVideo.HevcLevel/30.0)}else{'N/A'})","Chroma format:      $(NA $nativeVideo.Chroma)","Bit depth:          $($nativeVideo.BitDepth) bit","Temporal layers:    $(if($nativeVideo.HevcTemporalLayers -gt 0){$nativeVideo.HevcTemporalLayers}else{'N/A'})","Dependent slices:   $(if($nativeVideo.HevcDependentSliceSegments){'Enabled'}else{'Disabled'})","Extra header bits:  $($nativeVideo.HevcExtraSliceHeaderBits)","CABAC init flag:     $(if($nativeVideo.HevcCabacInitPresent){'Present'}else{'Not present'})","Default refs L0 / L1: $([int](1+$nativeVideo.HevcNumRefL0)) / $([int](1+$nativeVideo.HevcNumRefL1))","PPS initial QP:      $([int](26+$nativeVideo.HevcPicInitQpMinus26))","CU QP delta:         $(if($nativeVideo.HevcCuQpDeltaEnabled){'Enabled, depth '+$nativeVideo.HevcDiffCuQpDeltaDepth}else{'Disabled'})","Weighted P / B:      $(if($nativeVideo.HevcWeightedPred){'Yes'}else{'No'}) / $(if($nativeVideo.HevcWeightedBipred){'Yes'}else{'No'})","Tiles / WPP:         $(if($nativeVideo.HevcTilesEnabled){'Yes'}else{'No'}) / $(if($nativeVideo.HevcWppEnabled){'Yes'}else{'No'})","Deblocking control:  $(if($nativeVideo.HevcDeblockingControlPresent){'Present'}else{'Not present'})","Ref-list modification:  $(if($nativeVideo.HevcListsModificationPresent){'Present'}else{'Not present'})","Configuration:      hvcC / VPS + SPS + PPS")
            } elseif($nativeVideo.CodecId -eq 'V_MPEG4/ISO/AVC') {
                Add-CanonicalReportRows $canonicalReport @('','[ Native AVC Configuration ]','',"NAL length size:     $($nativeVideo.NalLengthSize) bytes","Chroma format:      $(NA $nativeVideo.Chroma)","Reference frames:   $(if($nativeVideo.RefFrames -gt 0){$nativeVideo.RefFrames}else{'N/A'})","Entropy coding:     $(if($nativeVideo.Cabac){'CABAC'}else{'CAVLC / N/A'})","Weighted prediction: $(if($nativeVideo.WeightedPred){'P slices - explicit'}else{'Disabled'})","Weighted bipred:    $(switch($nativeVideo.WeightedBipred){1{'Explicit'}2{'Implicit'}default{'Disabled'}})","8x8 transform:      $(if($nativeVideo.Transform8x8){'Yes'}else{'No / not signaled'})","Deblocking control:  $(if($nativeVideo.DeblockingFilterControlPresent){'Present'}else{'Not present'})","Redundant pic count: $(if($nativeVideo.RedundantPicCntPresent){'Present'}else{'Not present'})","PPS initial QP:      $([int](26+$nativeVideo.PicInitQpMinus26))")
            }
        }
    }

    if($video){
        $level=if($video.level){'{0:N1}' -f ([double]$video.level/10)}else{'N/A'}
        $depth=if($video.bits_per_raw_sample){$video.bits_per_raw_sample}elseif(([string]$video.pix_fmt)-match'(9|10|12|14|16)'){$matches[1]}else{8}
        $color="$(NA $video.color_primaries) / $(NA $video.color_transfer) / $(NA $video.color_space) / $(NA $video.color_range)"
        $displayParts=@((Display-Resolution $video) -split ' x ');$displayRatio=if($displayParts.Count -eq 2){Ratio ([long]$displayParts[0]) ([long]$displayParts[1])}else{'N/A'}
        Add-CanonicalReportRows $canonicalReport @('','[ Video ]','',"Codec:              $(NA $video.codec_long_name)",$(if($video.profile -and $level -ne 'N/A'){"Profile / Level:    $($video.profile)@L$level"}else{"Profile / Level:    N/A"}),"Resolution:         $($video.width) x $($video.height)","Display resolution: $(Display-Resolution $video)","Aspect ratio:       $(Ratio $video.width $video.height)","Display aspect ratio: $displayRatio",$(if((FPS $video) -ne 'N/A'){"Frame rate:         $(FPS $video) fps"}elseif($script:FrameResult -and $script:Duration -gt 0){"Frame rate:         $('{0:N3}' -f ($script:FrameResult.Count/$script:Duration)) fps (derived)"}else{"Frame rate:         N/A"}),"Pixel format:       $(NA $video.pix_fmt)","Bit depth:          $(if($depth -gt 0){'{0} bit' -f $depth}else{'N/A'})","Color:              $color")
        if($script:PacketResult){
            $r=$script:PacketResult
            $fv=0;if($script:FrameResult -and $script:Duration -gt 0){$fv=$script:FrameResult.Count/$script:Duration};$rr=$video.avg_frame_rate -split '/';if($fv -le 0 -and $rr.Count -eq 2 -and [double]$rr[1] -ne 0){$fv=[double]$rr[0]/[double]$rr[1]}
            $qf=if($fv -and $video.width -and $video.height){$r.Bitrate/([double]$video.width*$video.height*$fv)}else{0}
            $nativeVideoTrack=@($script:NativeInfo.Tracks|Where-Object{$_.Kind -eq 'video'})[0]
            $codecPrivateBytes=if($nativeVideoTrack -and $nativeVideoTrack.CodecPrivate){$nativeVideoTrack.CodecPrivate.Length}else{0}
            $encodedVideoTotal=$r.Total+$codecPrivateBytes
            Add-CanonicalReportRows $canonicalReport @("Packet engine:       $script:PacketEngine","Packets:            $('{0:N0}' -f $r.Count)","Key packets:        $('{0:N0}' -f $r.Key)","Packet payload:     $('{0:N0}' -f $r.Total) bytes ($(Bytes $r.Total))","Codec configuration: $('{0:N0}' -f $codecPrivateBytes) bytes","Encoded video total: $('{0:N0}' -f $encodedVideoTotal) bytes ($(Bytes $encodedVideoTotal))","Bitrate:            $(Rate $r.Bitrate)",$(if($fv -gt 0){"Qf:                 $('{0:N6}' -f $qf)"}else{"Qf:                 N/A"}),"Packet size:        avg $(Bytes ([long]$r.Average)), min $(Bytes $r.Minimum), max $(Bytes $r.Maximum)",$(if($r.Key -gt 1){"Key interval:       avg $('{0:N2}' -f $r.GopAverage), min $('{0:N0}' -f $r.GopMinimum), max $('{0:N0}' -f $r.GopMaximum)"}else{"Key interval:       N/A (fewer than two key packets)"}))
