function Get-NativePixelFormat($track) {
    if($null -eq $track -or $track.Kind -ne 'video'){return $null}
    $depth=if($track.BitDepth -gt 0){[int]$track.BitDepth}else{8}
    $base=switch([string]$track.Chroma){
        'Monochrome' {'gray'}
        'YUV 4:0:0' {'gray'}
        'YUV 4:2:0' {'yuv420p'}
        'YUV 4:2:2' {'yuv422p'}
        'YUV 4:4:4' {'yuv444p'}
        default {$null}
    }
    if(-not $base){return $null}
    if($depth -le 8){return $base}
    return ('{0}{1}le' -f $base,$depth)
}
function Build-NativeMetadata {
    if($null -eq $script:NativeInfo){throw 'Native media information is not available.'}
    $streams=New-Object Collections.Generic.List[object]
    $index=0
    foreach($t in $script:NativeInfo.Tracks){
        $codecName=switch($t.CodecId){'V_MPEG4/ISO/AVC'{'h264'};'V_MPEGH/ISO/HEVC'{'hevc'};'V_MPEGI/ISO/VVC'{'vvc'};'V_AV1'{'av1'};'V_AV2'{'av2'};'V_MPEG4/ISO/ASP'{'mpeg4'};'A_MPEG/L3'{'mp3'};'A_AC3'{'ac3'};'A_EAC3'{'eac3'};'A_PCM'{'pcm'};'A_AAC'{'aac'};default{$t.CodecId}}
        $codecLong=switch($t.CodecId){'V_MPEG4/ISO/AVC'{'H.264 / AVC'};'V_MPEGH/ISO/HEVC'{'H.265 / HEVC'};'V_MPEGI/ISO/VVC'{'H.266 / VVC'};'V_AV1'{'AV1'};'V_AV2'{'AV2 / AOMedia Video 2'};'V_MPEG4/ISO/ASP'{'MPEG-4 Part 2 / XviD'};'A_MPEG/L3'{'MP3'};'A_AC3'{'Dolby Digital / AC-3'};'A_EAC3'{'Dolby Digital Plus / E-AC-3'};'A_PCM'{if($t.PcmFloat){'PCM floating-point'}else{'PCM signed integer'}};'A_AAC'{'AAC'};default{$t.CodecId}}
        $streams.Add([pscustomobject]@{
            index=$index;codec_type=$t.Kind;codec_name=$codecName;codec_long_name=$codecLong;profile=if($t.Kind -eq 'video'){$t.Profile}elseif($t.Kind -eq 'audio'){$t.AudioProfile}else{$null};level=if($t.Level -gt 0){[int]([Math]::Round($t.Level*10))}else{$null}
            width=$t.Width;height=$t.Height;avg_frame_rate=if($t.FrameRate -gt 0){('{0}/1000' -f [int]([Math]::Round($t.FrameRate*1000)))}else{'0/0'};sample_aspect_ratio=if($t.PixelAspect){$t.PixelAspect}else{$null};display_aspect_ratio=$null
            pix_fmt=Get-NativePixelFormat $t;bits_per_raw_sample=if($t.BitDepth -gt 0){$t.BitDepth}else{$null};color_primaries=if($t.ColorPrimaries){$t.ColorPrimaries}else{$null};color_transfer=if($t.ColorTransfer){$t.ColorTransfer}else{$null};color_space=if($t.ColorMatrix){$t.ColorMatrix}else{$null};color_range=if($t.ColorRange){$t.ColorRange}else{$null}
            sample_rate=if($t.OutputSampleRate -gt 0){$t.OutputSampleRate}elseif($t.SamplingRate -gt 0){[int]$t.SamplingRate}else{$null};channels=if($t.AudioChannels -gt 0){$t.AudioChannels}elseif($t.Channels -gt 0){$t.Channels}else{$null};channel_layout=if($t.AudioChannels -eq 2){'stereo'}elseif($t.AudioChannels -eq 1){'mono'}else{$null};bit_rate=$t.AudioBitrate
            tags=[pscustomobject]@{language=if($t.Language){$t.Language}else{'und'}}
        });$index++
    }
    [pscustomobject]@{
        streams=$streams.ToArray()
        format=[pscustomobject]@{
            duration=$script:NativeInfo.DurationSeconds;format_name=$script:NativeInfo.DocType;format_long_name=$script:NativeInfo.Container
            tags=[pscustomobject]@{muxing_application=$script:NativeInfo.MuxingApp;writing_application=$script:NativeInfo.WritingApp}
        }
    }
}
function Build-Base($d) {
    $script:Meta=$d
    $script:Duration=if($d.format.duration){[double]$d.format.duration}else{0}
    $json.Text=$d | ConvertTo-Json -Depth 20
    $dt=New-Object Data.DataTable
    foreach($c in @('#','Type','Codec','Profile','Parameters','Rate','Bitrate','Language')){[void]$dt.Columns.Add($c)}
    foreach($x in @($d.streams)){$row=$dt.NewRow();$row.'#'=$x.index;$row.Type=$x.codec_type;$row.Codec=$x.codec_name;$row.Profile=$x.profile;$row.Parameters=if($x.codec_type -eq 'video'){"$($x.width) x $($x.height)"}elseif($x.codec_type -eq 'audio'){"$($x.channels) ch"}else{''};$row.Rate=if($x.codec_type -eq 'video'){FPS $x}else{$x.sample_rate};$row.Bitrate=Rate $x.bit_rate;$row.Language=if($x.tags.language){$x.tags.language}else{'und'};$dt.Rows.Add($row)}
    $grid.DataSource=$dt
    Render
}
function Test-NativeRuntime {
    $issues = New-Object Collections.Generic.List[string]

    if(-not ('NativeMediaProbe' -as [type])) {
        $issues.Add('NativeMediaProbe type is unavailable.')
    }
    if(-not ('NativeMatroskaPacketScan' -as [type])) {
        $issues.Add('NativeMatroskaPacketScan type is unavailable.')
    }
    if(-not ('H264CabacArithmeticDecoder' -as [type])) {
        $issues.Add('H264CabacArithmeticDecoder type is unavailable.')
    }
    try { $null=[H264CabacSelfTest]::Run() } catch { $issues.Add('CABAC self-test failed: '+$_.Exception.Message) }
    if($script:HostedInMemory -ne $true) {
        $issues.Add('In-memory host contract is not active.')
    }

    if($issues.Count -gt 0) {
        throw ($issues -join [Environment]::NewLine)
    }
}

function Complete-NativeMetadata {
    $script:ReadyModelStatus=if($script:ReadyMedia -and $script:ReadyMedia.IsValid){'PASS'}else{'INCOMPLETE'}
    Build-Base (Build-NativeMetadata)
    $status.Text='Metadata ready - codec analysis continues automatically...'
    Log ('Native pipeline: '+$script:NativeInfo.Container+' -> video-only preallocated sample index -> shared codec-private parser -> codec analyzer.')
    Log 'Runtime: in-memory EXE host compatible; no external process or temporary file path.'
    Log 'CABAC runtime self-test passed.';Log ('QP/DRF status: '+$script:QpDecoderState.Status+'. No estimated values will be shown.')
    $bar.Style='Continuous';$bar.MarqueeAnimationSpeed=0;$bar.Value=0
    $nativeVideo=@($script:NativeInfo.Tracks | Where-Object { $_.Kind -eq 'video' })[0]
    if($nativeVideo -and $nativeVideo.CodecId -eq 'V_AV1'){Log ('AV1: Sequence Header validated; starting native frame and Base Q analysis.')}
    Start-Scan
}

function Start-Meta($path) {
    Set-PreviewSource $previewA $path;$script:PreviewAIndex=0;$script:PreviewARunning=$false;$previewA.Play.Text='Play';$previewA.Position.Text='Axis: 0'
    if($script:ScanJob -or $script:Mp4PrepJob){return}
    Test-NativeRuntime
    $script:File=$path
    $script:ReferenceOnlyView=$false
    $script:TopChartMode='Bitrate';$script:RelativeQCache=$null
    $script:Meta=$null
    $script:PacketResult=$null
    $script:FrameResult=$null
        $script:BitrateBins=@()
    $script:QpCounts=@{}
    $script:QpMode='SliceQPY'
    $script:SliceQpDiagnostic=$null
    $script:HevcDiagnostic=$null;$script:Av1Diagnostic=$null;$script:CanonicalStatisticsResult=$null
    $script:Cancelled=$false
    if($script:Mp4PrepJob){$script:Mp4PrepJob.Dispose();$script:Mp4PrepJob=$null}
        $fileText.Text=$path
    $summary.Clear();$json.Clear();$log.Clear();$grid.DataSource=$null
    if($null -ne $chart){$chart.Invalidate()}
    if($null -ne $qpText){Render-QpHistogram}
    Busy $true
    $status.Text='Reading native metadata...'
    try {
        $script:NativeInfo=[NativeMediaProbe]::Inspect($path)
        if($script:NativeInfo.Container -eq 'MP4 / MOV'){
            $script:Mp4Probe=$null;$script:ReadyMedia=$null
            $script:Mp4PrepJob=New-Object NativeMp4PreparationJob
            $script:Mp4PrepJob.Start($path)
            $bar.Style='Marquee';$bar.MarqueeAnimationSpeed=25
            $status.Text=if($script:NativeInfo.Container -eq 'AVI'){'Reading AVI RIFF headers and idx1 index...'}else{'Reading MP4 sample tables and building index...'}
            Log 'MP4 preparation started on a background thread; deep analysis will continue automatically.'
            return
        } elseif($script:NativeInfo.Container -eq 'AVI'){
            $script:AviProbe=$null;$script:ReadyMedia=$null
            $script:Mp4PrepJob=New-Object NativeAviPreparationJob
            $script:Mp4PrepJob.Start($path)
            $bar.Style='Marquee';$bar.MarqueeAnimationSpeed=25
            $status.Text='Reading AVI RIFF headers and idx1 index...'
            Log 'AVI 1.0 preparation started on a background thread; canonical analysis will continue automatically.'
            return
        } elseif($script:NativeInfo.Container -eq 'Matroska / WebM'){
            $script:Mp4Probe=$null;$script:AviProbe=$null;$script:ReadyMedia=[LsdMatroskaAdapter]::Adapt($path,$script:NativeInfo)
        } else { throw 'The native-only build currently supports Matroska / WebM, AVI 1.0, and unfragmented MP4 / M4V / MOV files.' }
        Complete-NativeMetadata
    }
    catch {
        Busy $false
        Log ('Native load failed: '+$_.Exception.Message)
        [Windows.Forms.MessageBox]::Show($_.Exception.Message,'LSD native engine')|Out-Null
    }
}
function Update-CanonicalAudioAnalysis {
    $script:AudioDiagnostic=$null
    if(-not $script:ReadyMedia -or -not $script:File){return}
    $audioTrack=@($script:ReadyMedia.Tracks | Where-Object { $_.TrackType -eq 'audio' })[0]
    if($null -eq $audioTrack -or $audioTrack.Samples.Count -eq 0){return}
    $nativeAudio=@($script:NativeInfo.Tracks | Where-Object { $_.Kind -eq 'audio' })[0]
    $r=[CanonicalAudioAnalyzer]::Analyze($script:File,$audioTrack,[double]$script:Duration)
    $script:AudioDiagnostic=$r
    if($nativeAudio -and $r.Bitrate -gt 0){$nativeAudio.AudioPayloadBytes=$r.PayloadBytes;$nativeAudio.AudioBitrate=$r.Bitrate;if($r.SampleRate -gt 0){$nativeAudio.CoreSampleRate=$r.SampleRate;$nativeAudio.OutputSampleRate=$r.SampleRate;$nativeAudio.SamplingRate=$r.SampleRate};if($r.Channels -gt 0){$nativeAudio.CoreAudioChannels=$r.Channels;$nativeAudio.AudioChannels=$r.Channels;$nativeAudio.Channels=$r.Channels};if($r.DolbySampleRate -gt 0){$nativeAudio.CoreSampleRate=$r.DolbySampleRate;$nativeAudio.OutputSampleRate=$r.DolbySampleRate;$nativeAudio.SamplingRate=$r.DolbySampleRate};if($r.DolbyChannels -gt 0){$nativeAudio.CoreAudioChannels=$r.DolbyChannels;$nativeAudio.AudioChannels=$r.DolbyChannels;$nativeAudio.Channels=$r.DolbyChannels}}
    Build-Base (Build-NativeMetadata)
}

function Start-Scan {
    if(-not $script:Meta -or $script:ScanJob){return}
    $script:Cancelled=$false
    try {
        $container=$script:NativeInfo.Container
        $directCanonical=$container -in @('MP4 / MOV','AVI')
        $nativeVideo=@($script:NativeInfo.Tracks | Where-Object { $_.Kind -eq 'video' })[0]
        $nativeAudio=@($script:NativeInfo.Tracks | Where-Object { $_.Kind -eq 'audio' })[0]
        if($null -eq $nativeVideo){throw 'Native video track was not found.'}
        $script:ReadyTrack=@($script:ReadyMedia.Tracks | Where-Object { $_.TrackType -eq 'video' -and $_.TrackId -eq $nativeVideo.Number })[0]
        $script:ReadyAudioTrack=@($script:ReadyMedia.Tracks | Where-Object { $_.TrackType -eq 'audio' })[0]
        if($script:ReadyTrack -and -not $directCanonical){$script:ReadyTrack.Samples.Clear()}
        $script:ScanJob=New-Object NativeMatroskaPacketScan -ArgumentList ([double]$script:Duration),$nativeVideo,$script:ReadyTrack,([long]$script:ReadyMedia.TimecodeScale),$nativeAudio,$script:ReadyAudioTrack
        $script:PacketEngine=if($container -eq 'MP4 / MOV'){'Native C# MP4 canonical'}else{'Native C# Matroska preparation'}
        $script:StageStarted=[DateTime]::UtcNow
        if($directCanonical){Update-CanonicalAudioAnalysis;$script:ScanPhase='canonical';$script:ScanJob.StartCanonical($script:File)}else{$script:ScanPhase='container-index';$script:ScanJob.Start($script:File,[long]$nativeVideo.Number)}
        Busy $true
        $bar.Value=0
        $status.Text=if($script:ScanPhase -eq 'container-index'){'Phase 1/2 - indexing Matroska samples...'}else{'Analyzing canonical video samples...'}
    }
    catch {
        if($script:ScanJob){$script:ScanJob.Dispose()}
        $script:ScanJob=$null
        Busy $false
        Log ('Native analysis failed: '+$_.Exception.Message)
        [Windows.Forms.MessageBox]::Show($_.Exception.Message,'LSD native analysis error')|Out-Null
    }
}

function ConvertTo-QuantizerHistogram([string]$histogram) {
    $counts=@{}
    foreach($pair in ($histogram -split ',')) {
        if([string]::IsNullOrWhiteSpace($pair)){continue}
        $kv=$pair -split ':'
        if($kv.Count -ne 2){continue}
        $counts[[int]$kv[0]]=[long]$kv[1]
    }
    return $counts
}

function Finish-Scan([string]$value,$bins) {
    if($script:ReferenceResult){$script:ReferenceOnlyView=$false}
    $x=$value -split '\|'
    $result=[pscustomobject]@{Count=[long]$x[0];Key=[long]$x[1];Total=[long]$x[2];Minimum=[long]$x[3];Maximum=[long]$x[4];GopMinimum=[long]$x[5];GopMaximum=[long]$x[6];I=[long]$x[7];P=[long]$x[8];B=[long]$x[9];Other=[long]$x[10];Bitrate=[double]::Parse($x[11],[Globalization.CultureInfo]::InvariantCulture);Average=[double]::Parse($x[12],[Globalization.CultureInfo]::InvariantCulture);GopAverage=[double]::Parse($x[13],[Globalization.CultureInfo]::InvariantCulture)}
    $script:PacketResult=$result
    if(($result.I+$result.P+$result.B+$result.Other) -gt 0){$script:FrameResult=$result}
    $script:BitrateBins=@($bins)
    $reference.Enabled=$true
    if($null -ne $chart){$chart.Invalidate()}
    $hv=$script:NativeInfo.Tracks|Where-Object{$_.Type -eq 1}|Select-Object -First 1
    if($hv -and $hv.CodecId -eq 'V_MPEGI/ISO/VVC' -and $script:VvcDiagnostic -and $script:VvcDiagnostic.ShQpParsed -eq $script:VvcDiagnostic.Vcl -and $script:VvcDiagnostic.ShQpRejected -eq 0){
        $vvc=$script:VvcDiagnostic
        $hv.BitDepth=[int]$vvc.SpsBitDepth
        $hv.Chroma=switch([int]$vvc.SpsChromaFormat){0{'YUV 4:0:0'}1{'YUV 4:2:0'}2{'YUV 4:2:2'}3{'YUV 4:4:4'}default{''}}
        $metaVideo=$script:Meta.streams | Where-Object { $_.codec_type -eq 'video' } | Select-Object -First 1
        if($metaVideo){
            $metaVideo.bits_per_raw_sample=[int]$vvc.SpsBitDepth
            $metaVideo.pix_fmt=Get-NativePixelFormat $hv
        }
        $result.I=[long]$vvc.ShI
        $result.P=[long]$vvc.ShP
        $result.B=[long]$vvc.ShB
        $result.Other=[long]0
        $script:FrameResult=$result
        $vvcHistogram=@{}
        foreach($entry in $vvc.Index){
            if($entry.Vcl -and $entry.SliceQpY -ne 999){
                $q=[int]$entry.SliceQpY
                if($vvcHistogram.ContainsKey($q)){$vvcHistogram[$q]=[long]$vvcHistogram[$q]+1}else{$vvcHistogram[$q]=[long]1}
            }
        }
        $script:QpMode='VVC SliceQPY'
        $script:QpCounts=$vvcHistogram
    }
    if($hv -and $hv.CodecId -eq 'V_MPEGH/ISO/HEVC' -and $script:NativeHevcQpDiagnostic){
        $script:SliceQpDiagnostic=$script:NativeHevcQpDiagnostic
    }
    if($hv -and $hv.CodecId -eq 'V_AV2' -and $script:Av2Diagnostic -and $script:Av2Diagnostic.Pass2Rejected -eq 0 -and $script:Av2Diagnostic.BaseQTimelineCount -eq $script:Av2Diagnostic.Events){$script:QpMode='AV2 Base Q Index';$script:QpCounts=ConvertTo-QuantizerHistogram $script:Av2Diagnostic.BaseQHistogram}
