    if($hv -and $hv.CodecId -eq 'V_VP8' -and $script:Vp8Diagnostic -and $script:Vp8Diagnostic.Rejected -eq 0 -and $script:Vp8Diagnostic.Parsed -gt 0){$script:QpMode='VP8 Base Q Index';$script:QpCounts=ConvertTo-QuantizerHistogram $script:Vp8Diagnostic.Histogram}
    if($hv -and $hv.CodecId -eq 'V_VP9' -and $script:Vp9Diagnostic -and $script:Vp9Diagnostic.Rejected -eq 0 -and $script:Vp9Diagnostic.Parsed -gt 0){$script:QpMode='VP9 Base Q Index';$script:QpCounts=ConvertTo-QuantizerHistogram $script:Vp9Diagnostic.Histogram}
    if($hv -and $hv.CodecId -eq 'V_MPEG4/ISO/ASP' -and $script:Mpeg4Diagnostic -and $script:Mpeg4Diagnostic.Rejected -eq 0 -and $script:Mpeg4Diagnostic.Parsed -gt 0){$script:QpMode='MPEG-4 VOP Quantizer';$script:QpCounts=ConvertTo-QuantizerHistogram $script:Mpeg4Diagnostic.Histogram}
